static void AddWalkVelocityStatIfExistToPlayer(D2UnitStrc * pUnit, int32_t ePlayerClassId) {
    D2PoolManagerStrc* pMemory;
    eD2UnitType eUnitType;
    int32_t nUnitGUID;
    D2CharStatsTxt* pCharStatsTxt;
    if (!pUnit) {
      nUnitGUID = -1;
      eUnitType = UNIT_COUNT;
      pMemory = 0;
    } else {
      nUnitGUID = pUnit->nUnitGUID;
      eUnitType = pUnit->eUnitType;
      pMemory = pUnit->pMemory;
    }

    D2StatListExStrc* pStatEx = (D2StatListExStrc*)Stats::StatsEx::AllocStatList(pMemory, 4, 0, eUnitType, nUnitGUID);
    if (ePlayerClassId < 0 || ePlayerClassId >= sgptDataTable->nTxtCharStatsSize) {
      pCharStatsTxt = 0;
    } else {
      pCharStatsTxt = sgptDataTable->pTxtCharStats + ePlayerClassId;
    }
    if (!pCharStatsTxt->WalkVelocity) {
      return;
    }

    Stats::StatsEx::STATLIST_SetStatValue(pStatEx, UNITSTAT_velocitypercent, (int)((uint64_t)((uint32_t)(uint8_t)pCharStatsTxt->RunVelocity * 100) / (uint64_t)(int64_t)(int)(uint32_t)pCharStatsTxt->WalkVelocity) - 100, 0);
    Stats::StatsEx::STATLIST_AttachStatListToUnit(pUnit, pStatEx, 1);
}

